import {SLIDERS,sliderToValue} from './controls.mjs';
export function randomizeAdvanced(adapter,random=Math.random){const drift=sliderToValue('drift',random()),projection=[0,1,-1][Math.min(2,Math.floor(random()*3))];adapter.begin?.();try{adapter.slider('drift',drift);adapter.choice('projection',projection);}finally{adapter.end?.();}return{drift,projection};}
export function applyParameterPreset(preset,adapter){if(!preset||!preset.engine||!preset.audio)throw new Error('Invalid parameter preset');const values={...preset.engine,orbitEnabled:false,orbitRate:.07,orbitDepth:.7,...preset.audio};adapter.begin?.();try{for(const [name,value] of Object.entries(values))if(SLIDERS[name])adapter.slider(name,value);for(const name of ['mode','projection','pulseMode','tuningMode','root','scale','voiceLimit','octaves'])if(values[name]!==undefined)adapter.choice(name,values[name]);for(const name of ['pulseEnabled','droneEnabled','binaural','orbitEnabled'])if(values[name]!==undefined)adapter.toggle(name,!!values[name]);}finally{adapter.end?.();}return preset.name;}
